public class Filme implements Reproduzivel,Baixavel { private final String titulo; private final int duracao; private final long tamanho; private boolean baixado; public Filme(String t,int d,long s){titulo=t;duracao=d;tamanho=s;} public void reproduzir(){System.out.println("Reproduzindo filme: "+titulo);} public void pausar(){System.out.println("Pausando filme: "+titulo);} public void avaliar(int n){if(n<1||n>5)throw new IllegalArgumentException("Nota 1..5");} public String getTitulo(){return titulo;} public int getDuracao(){return duracao;} public void baixar(){baixado=true;} public void excluirDownload(){baixado=false;} public boolean isDisponivel(){return baixado;} public long getTamanhoMB(){return tamanho;} }
